#!/usr/bin/env python3
# Some portions generated by Codex. Separate diagnostics only.
import json,pathlib,hashlib
p=pathlib.Path(__file__).resolve().parent;arms=['base','depth','serializer','stack']; ss={a:json.loads((p/f'runs/profile-{a}/profile-summary.json').read_text()) for a in arms};nn={a:json.loads((p/f'runs/profile-{a}/node-summary.json').read_text()) for a in arms}
o=['# Separate corrected-consumer HTTP profiles','','Four separate JVMs, each 60 warmups and 20 recorded requests. Programmatic JFR begins after warmup; 128-frame recording/export. Node V8 main-isolate profiles cover each recorded client process lifetime, including startup/session GET/metrics and idle, not just POST. Native worker CPU including gzip decompression is not comprehensively sampled. Diagnostic durations are not clean benchmark observations. All profile requests passed the same route/output/no-spill/origin gates.','','## JVM execution samples','','Nearest categories are mutually exclusive sampled-stack classification. Inclusive mechanisms and ThreadLocal-visible samples overlap and must not be summed into total elapsed fractions. These are neither exact invocation counts nor wall-time percentages.','','| Arm | Java samples | TLS-visible | NDJSON nearest | Binding nearest | Lifetime nearest | Binary writer | Binary parser |','|---|---:|---:|---:|---:|---:|---:|---:|']
for a,x in ss.items():c=x['nearestCategories'];o.append(f"| {a} | {x['javaSamples']} | {x['threadLocalVisibleSamples']} | {c.get('workbench_ndjson',0)} | {c.get('snapshot_binding',0)} | {c.get('lifetime_read_replay',0)} | {c.get('binary_writer',0)} | {c.get('binary_parser',0)} |")
o+=['','## Inclusive dispatch and TLS caller witnesses','']
for a,x in ss.items():o += [f'### {a}',json.dumps(x['inclusiveMechanismWitnesses'],sort_keys=True),'',json.dumps(dict(list(x['threadLocalCallers'].items())[:10]),sort_keys=True),'']
o+=['## Corrected benchmark consumer','','The new client uses line-splitter.mjs: only the newly decoded chunk is searched; retained fragments join once when a delimiter is found. No accumulated prefix is rescanned. The generator yields immediately so the first rows-batch timestamp still follows that record’s JSON.parse before subsequent records are processed. This is a benchmark correction, not a Workbench browser fix: the frozen actual frontend already uses equivalent linear framing.','','V8 position ticks are sampled source positions, not exact operations or wall time. No controlled old-versus-new parser speedup is inferred from separate populations. Client JSON.parse is now line 34; splitter line 8 performs the delimiter search and line 17 joins completed fragments. Raw per-line maps below avoid attributing a moved helper name to eliminated work.','','| Arm | Node samples | Client source-line ticks | Splitter source-line ticks |','|---|---:|---|---|']
for a,x in nn.items():o.append(f"| {a} | {x['samples']} | {json.dumps(x['clientSourceLineTicks'],sort_keys=True)} | {json.dumps(x['splitterSourceLineTicks'],sort_keys=True)} |")
o+=['','## Leading Node leaves','']
for a,x in nn.items():o+=['### '+a]+[f'- {name}: {count}' for name,count in x['leafCounts'][:10]]
o+=['','## Allocation and native cautions','','Allocation sample weights are statistical weights, not exact allocated bytes or retained heap. Native accept/epoll/socket samples do not establish blocked duration or backpressure. Gzip work exists on both sides of the observed decoded stream; Node V8 samples omit some native-worker CPU. Pinned Jackson uses a concurrent-deque recycler, not ThreadLocal.']
for a,x in ss.items():o+=['',f"- {a} sampled allocation path weights: {json.dumps(x['sampledAllocationPathWeights'],sort_keys=True)}"]
o+=['','## Decision limits','','Use clean RESULTS.md for the matched outcome. Profiles identify mechanisms and remaining work; they do not prove the cause of arm differences, erase variability, or establish universal rollout/merge safety. No further optimization or clean rerun is included in this phase.']
(p/'HTTP-PROFILES.md').write_text('\n'.join(o)+'\n')
files=[f for a in arms for f in (p/f'runs/profile-{a}').iterdir() if f.name=='profile.jfr' or f.suffix=='.cpuprofile'];(p/'profile-artifacts.json').write_text(json.dumps({str(f.relative_to(p)):{'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'bytes':f.stat().st_size} for f in sorted(files)},indent=2))
